package com.healthcare.service;
import com.healthcare.dto.AppointmentDtos.*;import com.healthcare.entity.*;import com.healthcare.exception.ApiException;import com.healthcare.repository.*;import java.time.*;import java.util.*;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class AppointmentService {
 private final AppointmentRepository appointments;private final DoctorRepository doctors;private final PatientRepository patients;private final UserRepository users;
 public AppointmentService(AppointmentRepository a,DoctorRepository d,PatientRepository p,UserRepository u){appointments=a;doctors=d;patients=p;users=u;}
 @Transactional public View book(String email,Create req){Patient p=patients.findByUserId(user(email).getId()).orElseThrow(()->ApiException.forbidden());Doctor d=doctors.findById(req.doctorId()).orElseThrow(()->ApiException.notFound("Doctor not found"));Instant start=req.startAt();if(start.isBefore(Instant.now().plus(Duration.ofMinutes(5))))throw new ApiException(HttpStatus.BAD_REQUEST,"Appointment must be at least five minutes in the future");if(start.getNano()!=0||start.getEpochSecond()%60!=0)throw new ApiException(HttpStatus.BAD_REQUEST,"Appointment start must be aligned to a minute");Instant end=start.plus(Duration.ofMinutes(d.getSlotMinutes()));if(appointments.doctorBusy(d.getId(),start,end)||appointments.patientBusy(p.getId(),start,end))throw ApiException.conflict("The patient or doctor already has an appointment in this time slot");return View.from(appointments.save(new Appointment(p,d,start,end,req.reason())));}
 public List<View> mine(String email){AppUser u=user(email);if(u.getRole()==Role.PATIENT){var p=patients.findByUserId(u.getId()).orElseThrow(()->ApiException.forbidden());return appointments.findByPatientId(p.getId()).stream().map(View::from).toList();}if(u.getRole()==Role.DOCTOR){var d=doctors.findByUserId(u.getId()).orElseThrow(()->ApiException.forbidden());return appointments.findByDoctorId(d.getId()).stream().map(View::from).toList();}return appointments.findAll().stream().map(View::from).toList();}
 @Transactional public View cancel(Long id,String email){Appointment a=appointments.findById(id).orElseThrow(()->ApiException.notFound("Appointment not found"));AppUser u=user(email);boolean owns=u.getRole()==Role.ADMIN||(u.getRole()==Role.PATIENT&&a.getPatient().getUser().getId().equals(u.getId()))||(u.getRole()==Role.DOCTOR&&a.getDoctor().getUser().getId().equals(u.getId()));if(!owns)throw ApiException.forbidden();if(a.getStatus()==AppointmentStatus.COMPLETED||a.getStatus()==AppointmentStatus.CANCELLED)throw ApiException.conflict("This appointment can no longer be cancelled");a.setStatus(AppointmentStatus.CANCELLED);return View.from(a);}
 private AppUser user(String email){return users.findByEmailIgnoreCase(email).orElseThrow(ApiException::forbidden);}
}
